package dev.kuan.kuanperion.automation;
import java.nio.file.*;import java.util.*;
public final class JunkServiceTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[]args)throws Exception{
  var path=Files.createTempDirectory("junk-settings-test").resolve("automation.json");var store=AutomationSettingsStore.load(path);var fake=new JunkTaskTest.Fake();var coordinator=new AutomationCoordinator();var session=new AutomationSession(coordinator,fake::context,()->{},()->{});var receipts=new InventoryReceipts();var notices=new ArrayList<StashService.Notice>();var service=new JunkService(store,session,receipts,fake,()->true,notices::add);
  check(!service.autoEnabled()&&!Files.exists(path)&&!service.manualRequest(0),"defaults off/empty/no startup writes");
  service.setPolicy(JunkTaskTest.policy());service.setEnabled(true);var reloaded=AutomationSettingsStore.load(path);check(reloaded.junkPolicy().equals(JunkTaskTest.policy())&&reloaded.enabled(AutomationFeature.JUNK)&&!reloaded.enabled(AutomationFeature.AUTO_SELL)&&!reloaded.enabled(AutomationFeature.STASH),"independent policy and enabled persistence");
  service.tick(0);check(!service.active(),"inventory below threshold does not auto drop");check(service.manualRequest(0),"manual within authorized anchor");service.tick(0);service.setEnabled(false);check(!service.active()&&!service.autoEnabled(),"disable immediately cancels session");
  fake.ctx=new AutomationContext(1,true,false,Set.of());check(!service.recordAnchor(),"not Garden cannot record location");fake.ctx=new AutomationContext(1,true,true,Set.of());fake.location=new JunkPolicy.Location("overworld",99,70,99);check(service.recordAnchor()&&service.policy().anchor().equals(fake.location),"explicit record current Garden position");
  var before=Files.readString(path);Files.writeString(path,before+" ");try{service.setEnabled(true);throw new AssertionError("external config overwritten");}catch(java.io.IOException expected){}check(!service.autoEnabled(),"failed enable not silently active");check(Files.readString(path).equals(before+" "),"external settings preserved");
  var malformed=Files.createTempDirectory("junk-invalid").resolve("automation.json");Files.writeString(malformed,"{\"schemaVersion\":1,\"junk\":{\"allowedIds\":[\"SEEDS\"],\"maxItems\":0}}" );check(AutomationSettingsStore.load(malformed).junkPolicy().allowedIds().isEmpty(),"invalid limit fails closed, does not widen disposal");
  var good=new com.google.gson.Gson().toJsonTree(JunkTaskTest.policy()).getAsJsonObject();good.getAsJsonObject("anchor").addProperty("futureField","keep");var root=new com.google.gson.JsonObject();root.addProperty("schemaVersion",1);root.add("junk",good);Files.writeString(malformed,root.toString());var extended=AutomationSettingsStore.load(malformed);extended.setJunkPolicy(extended.junkPolicy());check(com.google.gson.JsonParser.parseString(Files.readString(malformed)).getAsJsonObject().getAsJsonObject("junk").getAsJsonObject("anchor").get("futureField").getAsString().equals("keep"),"deep unknown anchor fields preserved");
  good.getAsJsonObject("anchor").addProperty("x","10");Files.writeString(malformed,root.toString());check(AutomationSettingsStore.load(malformed).junkPolicy().allowedIds().isEmpty(),"numeric strings cannot silently authorize anchor");
  fake.ctx=new AutomationContext(1,true,true,Set.of());fake.visible=null;fake.location=JunkTaskTest.policy().anchor();var failures=AutomationSettingsStore.load(Files.createTempDirectory("junk-failed").resolve("automation.json"));var failed=new JunkService(failures,session,receipts,fake,()->true,notices::add);failed.setPolicy(JunkTaskTest.policy());failed.setEnabled(true);check(failed.manualRequest(10_000_000_000L),"failure fixture");failed.tick(10_000_000_000L);fake.accepted=false;failed.tick(11_000_000_000L);check(!failed.active()&&!failed.autoEnabled()&&!failures.enabled(AutomationFeature.JUNK),"uncertain/rejected drop disables automatic retry persistently");
  var automaticStore=AutomationSettingsStore.load(Files.createTempDirectory("junk-world-authorization").resolve("automation.json"));automaticStore.setJunkPolicy(JunkTaskTest.policy());automaticStore.setEnabled(AutomationFeature.JUNK,true);var full=new JunkTaskTest.Fake();full.fullInventory=true;var co=new AutomationCoordinator();var sess=new AutomationSession(co,full::context,()->{},()->{});var automatic=new JunkService(automaticStore,sess,new InventoryReceipts(),full,()->true,notices::add);automatic.tick(0);check(!automatic.active()&&full.opens==0,"saved enabled flag must not auto-drop in an unconfirmed world after restart");check(automatic.recordAnchor(),"record explicit world authorization");automatic.tick(2_000_000_000L);check(automatic.active()&&full.opens==1,"confirmed world and anchor permit automatic work");automatic.cancel(3_000_000_000L);full.ctx=new AutomationContext(2,true,true,Set.of());automatic.tick(100_000_000_000L);check(!automatic.active(),"new Garden at same coordinates needs fresh user authorization");
  System.out.println("JunkServiceTest: PASS (off/empty defaults, independent atomic persistence, threshold/manual/disable, explicit Garden anchor, conflicting write preservation)");
 }
}
